async function bootstrap() {
  ensureRequiredStartupEnv();

  const app = await NestFactory.create<NestExpressApplication>(AppModule, {
    // The instrument hook decorates providers for the same Observe module the
    // root imports; without the credentials neither exists, and instrumenting
    // instances that no tracer can record would be pointless (and would raise
    // from TracerService.createSpan if ever called). Same predicate as wiring:
    // one source of truth for "is Observe on".
    instrument: observeEnabled() ? ObserveInstrument : undefined,
  });
  // IP-scoped rate limiting keys on req.ip: behind the atmosphereinabox relay
  // every request arrives from the loopback Caddy, so express must resolve the
  // client from the relay's X-Forwarded-For hop — loopback peers only, or the
  // throttle key would be attacker-chosen (see trust-proxy.ts for the choice).
  trustLoopbackProxy(app.getHttpAdapter().getInstance());
  // Same-origin static mounts for the web foundation (fonts + island bundle).
  // Why here: these are middleware-level mounts registered before the router,
  // on the narrow /fonts and /islands prefixes no API route uses.
  // Why `new Logger` and not `app.get(Logger)`: the Logger token is not an
  // app-injectable provider in Nest 12, so resolving it from the container
  // throws UnknownElementException at boot; the Logger class is designed for
  // direct instantiation outside DI.
  registerStaticAssetMounts(app, new Logger('StaticAssets'));
  app.useGlobalPipes(
    new ValidationPipe({
      whitelist: true,
      forbidNonWhitelisted: true,
      transform: true,
    }),
  );

