/** Serves the comments page for one thread, keyed by its public local id — read-only HTML when signed out, write islands when signed in, moderation controls when a moderation actor resolves, and the effective content view (family-safe default, opt-in, or moderation) resolved server-side per request. */
export class ThreadCommentsPageController {
  constructor(private readonly loader: ThreadPageLoader) {}

  @Get(':threadId')
  async show(
    @Param('threadId') threadId: string,
    @Req() request: Request,
    @Res() response: Response,
    @Query('done') rawDone?: string | string[],
    @Query('sort') rawSort?: string | string[],
  ): Promise<Response> {
    // Security headers go on before anything can fail, so the 404 and 500
    // pages carry the same CSP as a successful render.
    applyPublicPageSecurityHeaders(response);

    // The loader owns every collaborator and every degradation (typed union
    // members); the renderer is pure; the adapter only picks the status and
    // sends. The local id is the only public identifier — AT-URIs never reach
    // the page. The sort key is parsed at this boundary (an unknown value falls
    // back to the default rather than 400ing a public page).
    const state = await this.loader.load(
      threadId,
      request,
      normalizeDone(rawDone),
      parseCommentSort(rawSort),
    );
    response
      .status(commentsPageStatus(state))
      .type('html')
      .send(renderCommentsPage(state));
    return response;
  }

