/** The friendly 404 for a thread local id that resolves to nothing. */
export interface NotFoundCommentsPageState {
  kind: 'not-found';
}

/** The calm taken-down notice page an ordinary viewer gets for a hidden thread. */
export interface TakenDownCommentsPageState {
  kind: 'taken-down';
  thread: PublicThreadSummary;
  bun: PublicBunSummary | null;
  done: DoneFlag | null;
}

/** The calm labeled-notice page a default-view visitor gets for a labeled thread. */
export interface LabeledCommentsPageState {
  kind: 'labeled';
  thread: PublicThreadSummary;
  bun: PublicBunSummary | null;
  viewer: PageViewer;
  done: DoneFlag | null;
}

/**
 * The calm age-gate page (Phase 11 Track B): the thread lives in a MATURE
 * bun, and the viewer is signed out or holds no age attestation. Signed-in
 * viewers get the attestation action inline; signed-out viewers get the
 * sign-in affordance. Moderation actors bypass (they see the page under the
 * moderation context), and the gate precedes the labeled branch — there is
 * nothing the labeled notice could show that the age gate may not.
 */
export interface AgeGatedCommentsPageState {
  kind: 'age-gated';
  thread: PublicThreadSummary;
  bun: PublicBunSummary | null;
  viewer: PageViewer;
  done: DoneFlag | null;
}

/** The retry page for a failed read (unknown thread or comment read outage). */
export interface ErrorCommentsPageState {
  kind: 'error';
  /** The local id from the request URL, for the retry link. */
  threadId: string;
}

/**
 * Everything the thread-comments page can render, one variant per page shape.
 * Session and read-context failures deliberately fold to the signed-out
 * default view (an expired or absent session is a normal signed-out page,
 * never an error), so they carry no extra state to render.
 */
export type CommentsPageState =
  | ReadyCommentsPageState
  | NotFoundCommentsPageState
  | TakenDownCommentsPageState

