/** Guards write endpoints by restoring a persisted OAuth session for the DID stored in the session cookie. */
export class OAuthSessionGuard implements CanActivate {
  // Both ports are required (Phase 9 A3 convention): the guard used to
  // tolerate absence by raw-constructing the Prisma resolver in its body — a
  // manual store `new` outside any factory that hid a hard dependency behind
  // optional-looking DI. OAuthSessionModule now supplies the one instance of
  // each.
  constructor(
    private readonly resolver: OAuthSessionAuthorPort,
    private readonly presence: OAuthSessionPresencePort,
  ) {}

  async canActivate(context: ExecutionContext): Promise<boolean> {
    const request = context
      .switchToHttp()
      .getRequest<
        Request & { [ATPROTO_AUTHOR_REQUEST_PROPERTY]?: AtprotoRequestAuthor }
      >();
    const author = await this.extractAuthor(request);

    if (!author) {
      throw new UnauthorizedException(
        'A valid ATProto OAuth session is required. Please sign in again.',
      );
    }

    request[ATPROTO_AUTHOR_REQUEST_PROPERTY] = author;
    return true;
  }

/** Creates a comment whose identity always comes from the authenticated author, never from client input. */
async create(
  input: CreateCommentInput,
  author: AtprotoRequestAuthor,
): Promise<CommentRecord> {
  const text = this.parseText(input.text);
  const threadId = parseThreadId(input.threadId);
  await this.assertThreadAcceptsComments(threadId);
  const parent = await this.resolveParent(input.parentId, threadId);
  const rootId = parent ? (parent.rootId ?? parent.id) : null;

  const created = await this.store.create({
    author: author.handle,
    text,
    threadId,
    parentId: parent ? parent.id : null,
    rootId,
    metadata: {
      authorDid: author.did,
      authorHandle: author.handle,
      userId: input.userId ?? null,
      bunId: input.bunId ?? null,
    },
  });
  await this.index.upsert(created);
  return created;
}

async create(input: AtprotoCommentWriteInput): Promise<CommentRecord> {
  return this.telemetry.pdsCall(
    'AtprotoCommentPdsAdapter.create',
    {
      operation: 'createRecord',
      userDid: input.metadata?.authorDid,
      tags: { threadId: input.threadId },
    },
    () => this.createUnspanned(input),
  );
}

private async createUnspanned(
  input: AtprotoCommentWriteInput,
): Promise<CommentRecord> {
  const authorDid =
    input.metadata?.authorDid ?? (await this.resolveDid(input.author));
  const authorHandle =
    input.metadata?.authorHandle ??
    (await this.resolveHandle(authorDid)) ??
    input.author;
  const agent = await this.oauthAgentForDid(authorDid);
  const rkey = randomUUID();
  const timestamp = new Date().toISOString();
  const record = {
    $type: COMMENT_COLLECTION,
    text: input.text,
    threadId: input.threadId,
    parentId: input.parentId,
    rootId: input.rootId,
    authorDid,
    authorHandle,
    userId: input.metadata?.userId ?? null,
    bunId: input.metadata?.bunId ?? null,
    createdAt: timestamp,
    updatedAt: timestamp,
  };
  const response = await agent.api.com.atproto.repo.createRecord({
    repo: authorDid,
    collection: COMMENT_COLLECTION,
    rkey,
    record,
  });

export class IndexWriter implements IndexWriteDelegate {
  constructor(
    private readonly threads: ThreadIndexWriteTarget,
    private readonly comments: CommentIndexWriteTarget,
    private readonly tags: TagIndexWriteTarget,
    private readonly onInvalidated?: InvalidationSink,
  ) {}

  async upsertThread(record: ThreadRecord): Promise<ThreadIndexEntry> {
    const entry = await this.threads.upsert(record);
    invalidateThreadScope(this.onInvalidated, record.bunId);
    return entry;
  }

  async reconcileThreads(
    bunId: string,
    records: ThreadRecord[],
  ): Promise<void> {
    await this.threads.reconcile(bunId, records);
    // A reconcile may prune rows as well as upsert, so the bun's whole thread
    // shape is stale regardless of what the records contained.
    invalidateThreadScope(this.onInvalidated, bunId);
  }

  async deleteThread(atprotoUri: string): Promise<void> {
    // Resolve the bun before the delete: after it, the row is gone and the
    // bun whose cached shape needs evicting is unknowable.
    const [entry] = await this.threads.listByAtprotoUris([atprotoUri]);
    await this.threads.deleteByAtprotoUri(atprotoUri);
    invalidateThreadScope(this.onInvalidated, entry?.bunId);
  }

