export class ThreadReconciler {
  constructor(
    private readonly buns: ReconcileBunSource,
    private readonly threads: ReconcileThreadSource,
    private readonly writer: ReconcileWriter,
    private readonly reportStep?: ReconcileStepReporter,
  ) {}

  /**
   * Reconciles the named buns and returns how many were processed. A bun whose
   * credentials vanished is skipped rather than failing the whole batch — one
   * unreadable bun must not stop the rest of the sync cycle. The PDS listing and
   * the index write are each timed and reported (F1.5) so the periodic sync's
   * per-step cost is visible without trace spans in the worker.
   */
  async reconcileBuns(bunIds: string[]): Promise<number> {
    let reconciled = 0;
    for (const bunId of bunIds) {
      const credentials = await this.buns.findCredentials(bunId);
      if (!credentials) {
        continue;
      }
      const records = await this.timedStep('list-threads', () =>
        this.threads.list(bunId, credentials),
      );
      await this.timedStep('write-reconcile', () =>
        this.writer.reconcileThreads(bunId, records),
      );
      reconciled += 1;
    }
    return reconciled;

