/** Islands the bundle can mount, keyed by the `data-island` attribute value. */
const islandRegistry = {
  hello: Hello,
  'comment-composer': CommentComposer,
  'comment-tools': CommentTools,
  'miller-columns': MillerColumns,
  'thread-manager': ThreadManager,
} as const;

/**
 * Mounts every registered island found under `root`.
 *
 * Important: unknown `data-island` names are deliberately ignored (not thrown)
 * so a stale cached bundle never breaks a page that references a newer island.
 */
export function mountIslands(root: ParentNode = document): void {
  const hosts = root.querySelectorAll<HTMLElement>('[data-island]');
  for (const host of hosts) {
    const name = host.dataset['island'];
    if (name === undefined || !(name in islandRegistry)) {
      continue;
    }
    mount(islandRegistry[name as keyof typeof islandRegistry], {
      target: host,
      // data-* attributes become props (dataset camelCases the names), so
      // pages configure islands through markup alone — no per-island glue.
      props: { ...host.dataset },
    });
  }
}
